// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to prevent underflow/overflow issues
        amount = bound(amount, 0, 1e30);

        // Call AdjustBetAmounts with the fuzzed amount
        c.AdjustBetAmounts(amount);

        // The general rule: currentDifficulty() must return the value of difficulty
        // Since difficulty is initially 0 and never changes in the reference, it should be 0
        // In the buggy version, currentDifficulty() returns difficulty * 2 = 0
        // Wait - this rule is too weak because both return 0 initially
        // We need a stronger rule: call AdjustDifficulty first to set difficulty, then check
        uint256 diff = 42; // Any non-zero value
        c.AdjustDifficulty(diff);
        assertTrue(c.currentDifficulty() == diff);
    }
}

